// Filter: only clients where 2+ days have passed since onboarding
const items = $input.all();
const now = Date.now();
const TWO_DAYS = 2 * 24 * 60 * 60 * 1000;

const due = items.filter(item => {
  const onboardedAt = item.json['timestamp'];
  if (!onboardedAt) return false;
  return (now - new Date(onboardedAt).getTime()) >= TWO_DAYS;
});

if (due.length === 0) return [];
return due;

const aiResps = $input.all();
const clients = $('🔍 Filter: 2+ Days Since Welcome').all();
return aiResps.map((aiResp, i) => {
  const client = clients[i]?.json || {};
  let email = {};
  try {
    const raw = aiResp.json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    email = JSON.parse(raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
  } catch (e) {
    email = {
      subject: `Quick follow-up — Scheduling our kickoff call for ${client['serviceRequired']}`,
      body: `Hi ${client['clientName']},\n\nHope you're doing well! Just following up on my welcome email from a couple of days ago. We're excited to get started on the ${client['serviceRequired']} project for ${client['clientCompany']}.\n\nWould any of these times work for a 30-minute kickoff call?\n- Tomorrow at 11 AM IST\n- Tomorrow at 3 PM IST\n- Day after at 10 AM IST\n\nLooking forward to kicking things off!\n\nBest regards`
    };
  }
  const formattedBody = (email.body || '').replace(/\n/g, '<br>') + `<br><div style="display:none!important">Ref ID: ${client.row_number}</div>`;
  return { json: { ...client, followUpSubject: email.subject, followUpBody: formattedBody } };
});

// Calculate week number for each active client
const items = $input.all();
const now = Date.now();

if (items.length === 0) return [];

return items.map(item => {
  const onboardedAt = item.json['timestamp'];
  let weekNum = 1;
  if (onboardedAt) {
    const daysSince = Math.floor((now - new Date(onboardedAt).getTime()) / (24 * 60 * 60 * 1000));
    weekNum = Math.max(1, Math.ceil(daysSince / 7));
  }
  return { json: { ...item.json, weekNumber: weekNum } };
});

const aiResps = $input.all();
const clients = $('🔢 Calculate Week Number').all();
return aiResps.map((aiResp, i) => {
  const client = clients[i]?.json || {};
  let email = {};
  try {
    const raw = aiResp.json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    email = JSON.parse(raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
  } catch (e) {
    email = {
      subject: `Week ${client.weekNumber} Check-In — ${client['serviceRequired']} for ${client['clientCompany']}`,
      body: `Hi ${client['clientName']},\n\nHappy Monday! Here's your Week ${client.weekNumber} update on the ${client['serviceRequired']} project.\n\nThis week's focus:\n- Continuing development on core features\n- Review session scheduled midweek\n\nDo you have any questions or concerns? Happy to hop on a quick call anytime.\n\nBest regards`
    };
  }
  const formattedBody = (email.body || '').replace(/\n/g, '<br>') + `<br><div style="display:none!important">Ref ID: ${client.row_number}</div>`;
  return { json: { ...client, checkinSubject: email.subject, checkinBody: formattedBody } };
});

// Merge client data with service database data
const serviceRow = $input.first().json;
const client = $('🔧 Parse Client Details').first().json;

const service = {
  id: serviceRow['Service ID'] || '',
  name: serviceRow['Service Name'] || '',
  description: serviceRow['Description'] || '',
  deliverables: (serviceRow['Deliverables'] || '').split('|').map(d => d.trim()).filter(Boolean),
  sopSteps: (serviceRow['SOP Steps'] || '').split('|').map(s => s.trim()).filter(Boolean),
  defaultTimeline: serviceRow['Default Timeline'] || '2 Weeks',
  toolsUsed: serviceRow['Tools Used'] || '',
  priceRange: serviceRow['Price Range (INR)'] || '',
  prerequisites: serviceRow['Prerequisites From Client'] || ''
};

return [{ json: { ...client, service } }];

const aiResp = $input.first().json;
const prev = $('🔀 Merge Client + Service Data').first().json;

let plan = {};
try {
  const raw = aiResp?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  plan = JSON.parse(raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
} catch (e) {
  // Fallback using database data directly
  const s = prev.service;
  plan = {
    project_title: `${s.name} for ${prev.clientCompany}`,
    calculated_timeline: s.defaultTimeline,
    welcome_message: `Welcome to ${prev.agencyName}! We are excited to build your ${s.name} solution.`,
    project_summary: `We will ${s.description} for ${prev.clientCompany}. ${prev.clientRequirements}`,
    roadmap: [{ week: 'Week 1', phase: 'Discovery & Setup', tasks: s.sopSteps.slice(0,4), deliverables_due: s.deliverables.slice(0,3), milestone: 'Project kickoff complete' }],
    deliverables_with_dates: s.deliverables.map((d, i) => ({ name: d, description: d, due_week: `Week ${Math.ceil((i+1) / 3)}`, owner: 'Agency' })),
    sop_for_client: s.sopSteps.map((step, i) => ({ step: i+1, title: step, description: step, duration: '2-3 days', client_action_needed: 'None' })),
    prerequisites_checklist: s.prerequisites.split(' and ').map(p => p.trim()),
    communication_plan: { kickoff: 'Within 2 days', updates: 'Weekly on Monday', reviews: 'End of each phase', escalation: 'Email with URGENT in subject' },
    payment_schedule: [{ milestone: 'Project Start', percentage: '50%', amount: `INR ${Math.round(parseInt(prev.budget)/2)}`, due: 'Before kickoff' }, { milestone: 'Project Completion', percentage: '50%', amount: `INR ${Math.round(parseInt(prev.budget)/2)}`, due: 'On delivery' }],
    tools_access_needed: s.toolsUsed.split(' and ').map(t => t.trim()),
    success_metrics: ['Project delivered on time', 'All deliverables approved by client', 'Client satisfaction score above 8/10'],
    warranty_and_support: '14-day post-launch support included',
    next_immediate_step: 'Schedule kickoff call within 48 hours'
  };
}

return [{ json: { ...prev, plan } }];

// Expand deliverables into individual rows for tracking
const d = $input.first().json;
const deliverables = d.plan.deliverables_with_dates || [];
const client = `${d.clientName} (${d.clientCompany})`;

if (deliverables.length === 0) return [];

return deliverables.map(del => ({ json: {
  Client: client,
  Company: d.clientCompany,
  Email: d.clientEmail,
  Service: d.service.name,
  Deliverable: del.name || '',
  Description: del.description || '',
  'Due Date': del.due_week || '',
  Week: del.due_week || '',
  Owner: del.owner || 'Agency',
  Status: 'Not Started',
  'Client Approval': 'Pending',
  Notes: '',
  'Onboarded At': d.timestamp
} }));

const d = $('🔀 Parse Project Plan').first().json;
const p = d.plan;
const s = d.service;

const colors = {
  bg: '#0d1117', card: '#161b22', border: '#1e293b',
  orange: '#f97316', blue: '#2563eb', teal: '#0d9488',
  green: '#22c55e', purple: '#8b5cf6', yellow: '#f59e0b',
  pink: '#ec4899', cyan: '#06b6d4', red: '#ef4444',
  white: '#ffffff', light: '#e2e8f0', gray: '#94a3b8', darkGray: '#475569'
};

const weekColors = [colors.orange, colors.blue, colors.teal, colors.green, colors.purple, colors.yellow, colors.pink, colors.cyan];

// ═══════════════════════════════════════════
// VISUAL ROADMAP TIMELINE
// ═══════════════════════════════════════════
const roadmap = p.roadmap || [];
const totalWeeks = roadmap.length;

const timelineHTML = roadmap.map((w, i) => {
  const clr = weekColors[i % weekColors.length];
  const isLast = i === totalWeeks - 1;
  const progressPct = Math.round(((i + 1) / totalWeeks) * 100);
  return '<table style="width:100%;border-collapse:collapse;margin:0;"><tr>' +
    '<td style="width:48px;vertical-align:top;padding:0;">' +
      '<table style="border-collapse:collapse;margin:0 auto;"><tr><td style="text-align:center;">' +
        '<div style="width:36px;height:36px;border-radius:50%;background:' + clr + ';color:#fff;text-align:center;line-height:36px;font-size:14px;font-weight:800;margin:0 auto;">' + (i + 1) + '</div>' +
        (!isLast ? '<div style="width:3px;height:80px;background:linear-gradient(' + clr + ',' + weekColors[(i+1) % weekColors.length] + ');margin:0 auto;"></div>' : '') +
      '</td></tr></table>' +
    '</td>' +
    '<td style="vertical-align:top;padding:0 0 16px 12px;">' +
      '<div style="background:' + colors.card + ';border-radius:8px;padding:14px 16px;border:1px solid ' + colors.border + ';border-left:3px solid ' + clr + ';">' +
        '<table style="width:100%;border-collapse:collapse;"><tr>' +
          '<td><h4 style="margin:0 0 2px;color:' + clr + ';font-size:15px;font-weight:700;">' + w.week + '</h4>' +
          '<p style="margin:0 0 8px;color:' + colors.white + ';font-size:13px;font-weight:600;">' + w.phase + '</p></td>' +
          '<td style="text-align:right;vertical-align:top;"><span style="background:' + clr + '22;color:' + clr + ';padding:3px 10px;border-radius:12px;font-size:11px;font-weight:600;">' + progressPct + '% Complete</span></td>' +
        '</tr></table>' +
        '<div style="margin:8px 0;">' +
          (w.tasks || []).map(task => 
            '<span style="display:inline-block;background:' + colors.bg + ';color:' + colors.light + ';padding:4px 10px;border-radius:4px;font-size:11px;margin:2px 4px 2px 0;border:1px solid ' + colors.border + ';">' + task + '</span>'
          ).join('') +
        '</div>' +
        '<table style="width:100%;border-collapse:collapse;margin:6px 0 0;"><tr>' +
          '<td style="padding:6px 0 0;border-top:1px solid ' + colors.border + ';">' +
            '<span style="color:' + colors.gray + ';font-size:11px;">📦 Deliverables: </span>' +
            '<span style="color:' + colors.light + ';font-size:11px;">' + (w.deliverables_due || []).join(' • ') + '</span>' +
          '</td>' +
        '</tr><tr>' +
          '<td style="padding:4px 0 0;">' +
            '<span style="color:' + colors.green + ';font-size:11px;">🏁 ' + (w.milestone || '') + '</span>' +
          '</td>' +
        '</tr></table>' +
      '</div>' +
    '</td>' +
  '</tr></table>';
}).join('');

// ═══════════════════════════════════════════
// VISUAL WORKFLOW DIAGRAM
// ═══════════════════════════════════════════
const sopSteps = p.sop_for_client || [];
const totalSteps = sopSteps.length;
const phaseSize = Math.ceil(totalSteps / 3);
const phases = [
  { name: 'DISCOVERY', icon: '🔍', color: colors.blue, steps: sopSteps.slice(0, phaseSize) },
  { name: 'BUILD', icon: '⚙️', color: colors.orange, steps: sopSteps.slice(phaseSize, phaseSize * 2) },
  { name: 'DELIVER', icon: '🚀', color: colors.green, steps: sopSteps.slice(phaseSize * 2) }
];

const workflowDiagramHTML = '<table style="width:100%;border-collapse:collapse;">' +
  '<tr>' +
  phases.map(ph => 
    '<td style="width:33.3%;text-align:center;padding:8px 4px;">' +
      '<div style="background:' + ph.color + '22;border:2px solid ' + ph.color + ';border-radius:12px;padding:12px 8px;">' +
        '<div style="font-size:24px;margin:0 0 4px;">' + ph.icon + '</div>' +
        '<div style="color:' + ph.color + ';font-size:13px;font-weight:800;letter-spacing:1px;">' + ph.name + '</div>' +
      '</div>' +
    '</td>'
  ).join('<td style="width:0;padding:8px 0;vertical-align:middle;text-align:center;"><span style="color:' + colors.orange + ';font-size:20px;">→</span></td>') +
  '</tr>' +
  '<tr>' +
  phases.map(ph =>
    '<td style="vertical-align:top;padding:4px;">' +
      ph.steps.map(step =>
        '<div style="background:' + colors.bg + ';border-radius:6px;padding:8px 10px;margin:4px 0;border:1px solid ' + colors.border + ';">' +
          '<table style="width:100%;border-collapse:collapse;"><tr>' +
            '<td style="width:24px;vertical-align:top;"><span style="color:' + ph.color + ';font-weight:bold;font-size:12px;">' + step.step + '.</span></td>' +
            '<td><span style="color:' + colors.light + ';font-size:11px;">' + step.title + '</span></td>' +
          '</tr></table>' +
        '</div>'
      ).join('') +
    '</td>'
  ).join('<td style="width:0;"></td>') +
  '</tr></table>';

// ═══════════════════════════════════════════
// PROGRESS BAR
// ═══════════════════════════════════════════
const progressBarHTML = '<table style="width:100%;border-collapse:collapse;margin:0 0 20px;">' +
  '<tr><td style="padding:0 0 6px;"><table style="width:100%;border-collapse:collapse;"><tr>' +
    '<td style="color:' + colors.gray + ';font-size:12px;">Project Start</td>' +
    '<td style="text-align:center;color:' + colors.orange + ';font-size:12px;font-weight:600;">' + p.calculated_timeline + '</td>' +
    '<td style="text-align:right;color:' + colors.green + ';font-size:12px;">🎯 Launch</td>' +
  '</tr></table></td></tr>' +
  '<tr><td style="padding:0;">' +
    '<div style="background:' + colors.border + ';border-radius:6px;height:10px;overflow:hidden;">' +
      '<div style="background:linear-gradient(90deg,' + colors.orange + ',' + colors.yellow + ',' + colors.green + ');height:10px;width:8%;border-radius:6px;"></div>' +
    '</div>' +
  '</td></tr>' +
  '<tr><td style="padding:4px 0 0;"><table style="width:100%;border-collapse:collapse;"><tr>' +
    roadmap.map((w, i) => {
      const clr = weekColors[i % weekColors.length];
      return '<td style="text-align:center;"><span style="color:' + clr + ';font-size:10px;font-weight:600;">W' + (i+1) + '</span></td>';
    }).join('') +
  '</tr></table></td></tr></table>';

// ═══════════════════════════════════════════
// SOP SECTION (Built BEFORE email assembly)
// ═══════════════════════════════════════════
const sopTableHTML = (p.sop_for_client || []).map((step, i) => {
  const clr = weekColors[i % weekColors.length];
  const hasClientAction = step.client_action_needed && step.client_action_needed !== 'None';
  return '<table style="width:100%;border-collapse:collapse;margin:0 0 8px;"><tr>' +
    '<td style="background:' + colors.bg + ';border-radius:8px;padding:14px;border:1px solid ' + colors.border + ';">' +
      '<table style="width:100%;border-collapse:collapse;"><tr>' +
        '<td style="width:40px;vertical-align:top;">' +
          '<div style="width:32px;height:32px;background:' + clr + ';border-radius:50%;text-align:center;line-height:32px;color:#fff;font-size:14px;font-weight:800;">' + step.step + '</div>' +
        '</td>' +
        '<td style="vertical-align:top;padding-left:12px;">' +
          '<p style="color:' + colors.white + ';font-size:14px;font-weight:700;margin:0 0 4px;">' + step.title + '</p>' +
          '<p style="color:' + colors.gray + ';font-size:12px;line-height:1.6;margin:0 0 6px;">' + step.description + '</p>' +
          '<table style="border-collapse:collapse;"><tr>' +
            '<td style="padding-right:16px;"><span style="color:' + colors.teal + ';font-size:11px;">⏱ ' + step.duration + '</span></td>' +
            (hasClientAction ? '<td><span style="background:' + colors.yellow + '22;color:' + colors.yellow + ';padding:2px 8px;border-radius:10px;font-size:10px;font-weight:600;">👤 Client: ' + step.client_action_needed + '</span></td>' : '') +
          '</tr></table>' +
        '</td>' +
      '</tr></table>' +
    '</td>' +
  '</tr></table>';
}).join('');

// ═══════════════════════════════════════════
// DELIVERABLES TABLE
// ═══════════════════════════════════════════
const delHTML = (p.deliverables_with_dates || []).map((del, i) => {
  const clr = weekColors[i % weekColors.length];
  return '<tr style="border-bottom:1px solid ' + colors.border + ';">' +
    '<td style="padding:10px 12px;"><table style="border-collapse:collapse;"><tr>' +
      '<td style="width:24px;vertical-align:top;"><div style="width:20px;height:20px;border:2px solid ' + clr + ';border-radius:4px;text-align:center;line-height:18px;font-size:10px;color:' + clr + ';">☐</div></td>' +
      '<td style="padding-left:8px;"><span style="color:' + colors.white + ';font-size:13px;font-weight:600;">' + del.name + '</span><br>' +
        '<span style="color:' + colors.gray + ';font-size:11px;">' + del.description + '</span></td>' +
    '</tr></table></td>' +
    '<td style="padding:10px 12px;text-align:center;"><span style="background:' + clr + '22;color:' + clr + ';padding:3px 10px;border-radius:10px;font-size:11px;font-weight:600;">' + del.due_week + '</span></td>' +
    '<td style="padding:10px 12px;color:' + colors.gray + ';font-size:12px;text-align:center;">' + del.owner + '</td>' +
  '</tr>';
}).join('');

// ═══════════════════════════════════════════
// PREREQUISITES
// ═══════════════════════════════════════════
const prereqHTML = (p.prerequisites_checklist || []).map((item, i) =>
  '<tr><td style="padding:10px 12px;border-bottom:1px solid ' + colors.border + ';">' +
    '<table style="border-collapse:collapse;"><tr>' +
      '<td style="width:28px;vertical-align:top;"><div style="width:22px;height:22px;border:2px solid ' + colors.purple + ';border-radius:50%;text-align:center;line-height:20px;font-size:10px;color:' + colors.purple + ';">' + (i+1) + '</div></td>' +
      '<td style="padding-left:8px;color:' + colors.light + ';font-size:13px;">' + item + '</td>' +
    '</tr></table>' +
  '</td></tr>'
).join('');

// ═══════════════════════════════════════════
// PAYMENT SCHEDULE
// ═══════════════════════════════════════════
const paymentHTML = (p.payment_schedule || []).map((pay, i) => {
  const pct = parseInt(pay.percentage) || 50;
  const clr = i === 0 ? colors.orange : colors.green;
  return '<tr style="border-bottom:1px solid ' + colors.border + ';">' +
    '<td style="padding:12px;"><span style="color:' + colors.white + ';font-size:13px;font-weight:600;">' + pay.milestone + '</span><br>' +
      '<span style="color:' + colors.gray + ';font-size:11px;">' + pay.due + '</span></td>' +
    '<td style="padding:12px;text-align:center;">' +
      '<div style="background:' + colors.border + ';border-radius:4px;height:8px;width:100px;display:inline-block;overflow:hidden;">' +
        '<div style="background:' + clr + ';height:8px;width:' + pct + '%;border-radius:4px;"></div>' +
      '</div>' +
      '<br><span style="color:' + clr + ';font-size:12px;font-weight:700;">' + pay.percentage + '</span>' +
    '</td>' +
    '<td style="padding:12px;text-align:right;"><span style="color:' + colors.green + ';font-size:15px;font-weight:800;">' + pay.amount + '</span></td>' +
  '</tr>';
}).join('');

// ═══════════════════════════════════════════
// COMMUNICATION PLAN
// ═══════════════════════════════════════════
const comm = p.communication_plan || {};
const commItems = [
  { icon: '📞', label: 'Kickoff', value: comm.kickoff || '', color: colors.blue },
  { icon: '📊', label: 'Updates', value: comm.updates || '', color: colors.orange },
  { icon: '🔍', label: 'Reviews', value: comm.reviews || '', color: colors.teal },
  { icon: '🚨', label: 'Escalation', value: comm.escalation || '', color: colors.red }
];

const commHTML = '<table style="width:100%;border-collapse:collapse;"><tr>' +
  commItems.map(c =>
    '<td style="width:25%;padding:4px;vertical-align:top;">' +
      '<div style="background:' + colors.bg + ';border-radius:8px;padding:12px 8px;text-align:center;border:1px solid ' + colors.border + ';min-height:80px;">' +
        '<div style="font-size:20px;margin:0 0 6px;">' + c.icon + '</div>' +
        '<div style="color:' + c.color + ';font-size:11px;font-weight:700;margin:0 0 4px;">' + c.label + '</div>' +
        '<div style="color:' + colors.light + ';font-size:11px;">' + c.value + '</div>' +
      '</div>' +
    '</td>'
  ).join('') +
'</tr></table>';

// ═══════════════════════════════════════════
// SUCCESS METRICS
// ═══════════════════════════════════════════
const metricsHTML = (p.success_metrics || []).map(m =>
  '<tr><td style="padding:8px 12px;border-bottom:1px solid ' + colors.border + ';">' +
    '<table style="border-collapse:collapse;"><tr>' +
      '<td style="width:28px;vertical-align:top;"><div style="width:22px;height:22px;background:' + colors.green + '22;border-radius:50%;text-align:center;line-height:22px;font-size:12px;">✓</div></td>' +
      '<td style="padding-left:8px;color:' + colors.light + ';font-size:13px;">' + m + '</td>' +
    '</tr></table>' +
  '</td></tr>'
).join('');

// ═══════════════════════════════════════════
// SECTION BUILDER
// ═══════════════════════════════════════════
const section = (icon, title, content, borderColor) =>
  '<div style="margin-bottom:20px;"><div style="background:' + colors.card + ';border-radius:10px;overflow:hidden;border:1px solid ' + colors.border + ';">' +
  '<div style="background:linear-gradient(135deg,' + borderColor + ' 0%,' + borderColor + '99 100%);padding:14px 18px;">' +
  '<h2 style="margin:0;color:' + colors.white + ';font-size:15px;font-weight:700;">' + icon + '  ' + title + '</h2></div>' +
  '<div style="padding:18px;">' + content + '</div></div></div>';

// ═══════════════════════════════════════════
// ASSEMBLE THE COMPLETE EMAIL
// ═══════════════════════════════════════════
const clientEmail = '<div style="background:' + colors.bg + ';padding:0;font-family:Segoe UI,Arial,sans-serif;max-width:720px;margin:0 auto;">' +

'<div style="background:linear-gradient(135deg,#f97316 0%,#ea580c 50%,#dc2626 100%);padding:36px 28px;text-align:center;border-radius:10px 10px 0 0;">' +
'<div style="font-size:40px;margin:0 0 8px;">🚀</div>' +
'<h1 style="margin:0;color:' + colors.white + ';font-size:24px;font-weight:800;letter-spacing:-0.5px;">Welcome to ' + d.agencyName + '</h1>' +
'<p style="margin:8px 0 0;color:#fed7aa;font-size:15px;">' + (p.project_title || '') + '</p>' +
'<div style="margin:16px auto 0;width:60px;height:3px;background:#ffffff44;border-radius:2px;"></div>' +
'</div>' +

'<div style="background:' + colors.card + ';padding:28px;border:1px solid ' + colors.border + ';border-top:none;">' +

'<p style="color:' + colors.light + ';font-size:16px;line-height:1.7;margin:0 0 8px;">Dear ' + d.clientName + ',</p>' +
